-- ============================================================
--  module-steam-energy: 스팀에너지관리 하위 메뉴 (그룹 + 페이지)
--  STEAM_ENERGY_MGMT(상위) 아래 그룹, 각 그룹 아래 페이지 메뉴.
--  각 페이지 menu_url = /steam/{page}.html  (SPA 가 iframe 으로 로드)
--  재실행 안전: 기존 STEAM_ 하위 메뉴/권한 삭제 후 재삽입.
--  ※ 운영 DB 에서 메뉴를 바꿨다면 이 파일도 함께 갱신할 것.
-- ============================================================

-- 기존 스팀 하위 메뉴 정리 (상위 STEAM_ENERGY_MGMT 는 유지)
DELETE rm FROM core_role_menu rm JOIN core_menu m ON rm.MENU_ID=m.MENU_ID
  WHERE m.MENU_CODE LIKE 'STEAM_%' AND m.MENU_CODE <> 'STEAM_ENERGY_MGMT';
DELETE FROM core_menu WHERE MENU_CODE LIKE 'STEAM_%' AND MENU_CODE <> 'STEAM_ENERGY_MGMT';

-- 레거시 셸(/steam/index.html) 폐기: 상위 메뉴는 URL 없는 그룹으로만 사용
UPDATE core_menu SET MENU_NAME='스팀에너지관리', MENU_URL=NULL, SORT_ORDER=40 WHERE MENU_CODE='STEAM_ENERGY_MGMT';

-- 그룹 (parent = STEAM_ENERGY_MGMT)

